-- Expect exactly 144 daily_options rows inserted above across 36 daily_questions rows.

-- V1 release execution (2026-11-04): admin_publish_daily() refuses to publish any Daily
-- whose approved_content_version is null, or that no longer matches a freshly recomputed
-- fingerprint (admin_compute_daily_fingerprint) -- confirmed by reading its real body. Every
-- row inserted above would otherwise fail that check forever (approved_content_version was
-- never set). Calling the REAL fingerprint function here (never reimplemented in a generator
-- script) records a correct, self-consistent "approval" against each row's actual current
-- content -- the same thing admin_approve_daily itself would set, had it been run through
-- the admin UI with a real session instead of this direct seed. approved_by is the real,
-- current owner (looked up dynamically, never a hardcoded id) rather than auth.uid(), which
-- is null in this raw-SQL context (no JWT session) -- the same reason the archival script
-- in this same directory cannot call admin_archive_live_daily() directly either.
do $$
declare
  v_admin_id uuid;
begin
  select user_id into v_admin_id from public.admin_users where role = 'owner';
  if v_admin_id is null then
    raise exception 'No admin_users row with role = owner found -- cannot record an approval attribution. Aborting.';
  end if;
  update public.daily_questions
  set approved_by = v_admin_id,
      approved_at = now(),
      approved_content_version = public.admin_compute_daily_fingerprint(id)
  where status = 'Approved' and approved_content_version is null;
end $$;

commit;
